mapper.select:
select u.user_id, u.dept_id as userDeptId, u.user_name, u.nick_name, u.email, u.avatar, u.phonenumber, u.password, u.sex, u.status, u.del_flag, u.login_ip, u.login_date, u.create_by, u.create_time, uf.remark,uf.degree_max,uf.work_address,uf.expatriate_country,uf.graduate_max,uf.address,uf.address_details,uf.expatriate_year,uf.professional, uf.draguate_school,uf.family_address,uf.kpi_result_recent,uf.political_landscape,uf.onboard_date_cn,uf.landline_number,uf.salary_scale, uf.birth_date,uf.positive_date,uf.outsite_date_sum,uf.party_date,uf.onboard_date_world,uf.outsite_country_all,uf.local_longitude,uf.local_latitude,uf.parent_id,uu.user_name as usersuperiorname, d.dept_id, d.parent_id as deptParentid, d.ancestors, d.dept_name, d.order_num, d.leader, d.status as dept_status, r.role_id, r.role_name, r.role_key, r.role_sort, r.data_scope, r.status as role_status from sys_user u left join sys_userinfo uf on u.user_id = uf.user_id left join sys_user uu on uu.user_id = uf.parent_id left join sys_dept d on u.dept_id = d.dept_id left join sys_user_role ur on u.user_id = ur.user_id left join sys_role r on r.role_id = ur.role_id where u.del_flag = '0'
AND u.user_id = #{userId}
AND u.user_name like concat('%', #{userName}, '%')
AND u.status = #{status}
AND u.phonenumber like concat('%', #{phonenumber}, '%')
AND date_format(u.create_time,'%y%m%d') >= date_format(#{params.beginTime},'%y%m%d')
AND date_format(u.create_time,'%y%m%d') <= date_format(#{params.endTime},'%y%m%d')
AND (u.dept_id = #{deptId} OR u.dept_id IN ( SELECT t.dept_id FROM sys_dept t WHERE find_in_set(#{deptId}, ancestors) ))
-- ${params.dataScope}

select distinct u.user_id, u.dept_id as userDeptId, u.user_name, u.nick_name, u.email, u.phonenumber, u.status, u.create_time, uf.remark,uf.degree_max,uf.work_address,uf.expatriate_country,uf.graduate_max,uf.address,uf.address_details,uf.expatriate_year,uf.professional, uf.draguate_school,uf.parent_id,uf.family_address,uf.kpi_result_recent,uf.political_landscape,uf.onboard_date_cn,uf.landline_number,uf.salary_scale, uf.birth_date,uf.positive_date,uf.outsite_date_sum,uf.party_date,uf.onboard_date_world,uf.outsite_country_all,uf.local_longitude,uf.local_latitude,uu.user_name as usersuperiorname from sys_user u left join sys_userinfo uf on u.user_id = uf.user_id left join sys_user uu on uu.user_id = uf.parent_id left join sys_dept d on u.dept_id = d.dept_id left join sys_user_role ur on u.user_id = ur.user_id left join sys_role r on r.role_id = ur.role_id where u.del_flag = '0' and r.role_id = #{roleId}
AND u.user_name like concat('%', #{userName}, '%')
AND u.phonenumber like concat('%', #{phonenumber}, '%')
-- ${params.dataScope}

mapper.insert:
insert into sys_user(
user_id, dept_id, user_name, nick_name, email, avatar, phonenumber, sex, password, status, login_ip, login_date, create_by, create_time
)values(
#{userId}, #{deptId}, #{userName}, #{nickName}, #{email}, #{avatar}, #{phonenumber}, #{sex}, #{password}, #{status}, #{loginIp}, #{loginDate}, #{createBy}, sysdate()
)

insert into sys_userinfo(
user_id, remark, degree_max, work_address, expatriate_country, graduate_max, address, address_details, expatriate_year, professional, draguate_school, parent_id, family_address, kpi_result_recent, political_landscape, onboard_date_cn, landline_number, salary_scale, birth_date, positive_date, outsite_date_sum, party_date, onboard_date_world, outsite_country_all, local_longitude, local_latitude,
)values(
#{userId}, #{remark}, #{degreeMax}, #{workAddress}, #{expatriateCountry}, #{graduateMax}, #{address}, #{addressDetails}, #{expatriateYear}, #{professional}, #{draguateSchool}, #{parentId}, #{familyAddress}, #{kpiResultRecent}, #{politicalLandscape}, #{onboardDateCn}, #{landlineNumber}, #{salaryScale}, #{birthDate}, #{positiveDate}, #{outsiteDateSum}, #{partyDate}, #{onboardDateWorld}, #{outsiteCountryAll}, #{localLongitude}, #{localLatitude},
)
